with valid as (select *, coalesce(balance, 0) as balance_filled, concat(status, ' ', account_type) as status_account_type, coalesce(status, 'N/A') as resolved_status from accounts where status is not null) select id, customer_id, opened_date, status, balance_filled, resolved_status, avg(balance_filled) over (partition by customer_id, account_type order by balance_filled, id rows between unbounded preceding and current row) as running_avg_balance_filled, min(balance_filled) over (partition by customer_id, account_type order by balance_filled, id rows between unbounded preceding and current row) as running_min_balance_filled, max(balance_filled) over (partition by customer_id, account_type order by balance_filled, id rows between unbounded preceding and current row) as running_max_balance_filled from valid;
